  p_Name_37a14b47ae60 := 'Kev-0.8B';
  p_Description_37a14b47ae60 := 'The 0.8B model of Kev 1.0, Jared Palmer''s open-weight (Apache-2.0) family of decision models: a LoRA adapter and a pointer head on Qwen3.5-0.8B-Base. It answers Likelihood, Choice (up to 255 options) and Score (2 to 10 levels) questions with a probability for every allowed option, takes the same System One request as Jev, and writes no text. Each checkpoint ships with a fitted temperature; set thresholds on your own data. Its model card validates states of up to 8,192 tokens. It is the smallest Kev, for when size matters more than accuracy. It is self-hosted: MJ reaches it through the System One Endpoint vendor and the SystemOneDecision driver, at any server with a /v1/systemone route, such as Kev''s own server (for example deployed on Modal) or llama.cpp''s llama-server, with the endpoint in an API Key with Endpoint credential bound to this model''s row.';
