  p_Description_297f0a1761d0 := 'Perplexity''s 27B open-weight decision model, pplx-decider-v1-27b (Apache-2.0, released October 1, 2026), fine-tuned from Qwen3.8-27B. It answers Likelihood, Choice (up to 255 options) and Score (up to 10 levels) questions, up to 128 in one call, about a state of up to 262,144 input tokens (the questions included), and returns a probability for every option or level. It writes no text. It takes the same System One request as Jev. Its only managed host is Perplexity''s Decisions API (POST https://api.perplexity.ai/v1/decisions), limited to 10 requests per second per organization; running the open weights yourself needs a CUDA GPU with about 49 GiB for the weights and Perplexity''s own Python inference code, which has no HTTP server. Perplexity reports 85.71% accuracy overall on 11 public benchmarks it chose, against 84.51% for Jev, with Jev ahead on 6 of the 11; those are Perplexity''s figures, not MJ''s measurements. The API also accepts images with the state, which MJ does not send yet. Its raw probabilities are not calibrated to MJ''s data, so set thresholds on calibrated values.';
