    /* ===== FOOTER ===== */
    .report-footer {
      margin-top: 60px;
      padding-top: 30px;
      border-top: 2px solid var(--border-color);
      text-align: center;
      color: #666;
      font-size: 0.9em;
    }

    /* ===== PRINT STYLES ===== */
    @media print {
      body {
        max-width: 100%;
        padding: 0;
      }

      .report-header {
        background: var(--primary-color);
        print-color-adjust: exact;
        -webkit-print-color-adjust: exact;
      }

      .no-print {
        display: none !important;
      }

      h1, h2, h3 {
        page-break-after: avoid;
      }

      .finding-card, .source-card, details {
        page-break-inside: avoid;
      }

      details {
        border: 1px solid var(--border-color);
      }

      summary {
        display: none;
      }

      details[open] {
        display: block;
      }

      a {
        text-decoration: none;
        color: var(--primary-color);
      }

      a[href]:after {
        content: " (" attr(href) ")";
        font-size: 0.8em;
        font-style: italic;
      }
    }
  </style>
</head>
<body>
  <!-- HEADER -->
  <div class="report-header">
    <h1>[Report Title]</h1>
    <p>[Report Description]</p>
    <div class="report-meta">
      <div class="report-meta-item">
        <strong>Research Goal:</strong><br>[metadata.researchGoal]
      </div>
      <div class="report-meta-item">
        <strong>Sources:</strong><br>[metadata.totalSourcesGathered]
      </div>
      <div class="report-meta-item">
        <strong>Iterations:</strong><br>[metadata.iterationCount]
      </div>
      <div class="report-meta-item">
        <strong>Completed:</strong><br>[Date]
      </div>
    </div>
  </div>

  <!-- EXECUTIVE SUMMARY -->
  <div class="executive-summary">
    <h2>Executive Summary</h2>
    <p>[synthesis.executiveSummary]</p>
  </div>

  <!-- KEY TAKEAWAYS -->
  <div class="key-takeaways">
    <h3>Key Takeaways</h3>
    <ul>
      <li>[Takeaway 1]</li>
      <li>[Takeaway 2]</li>
      <li>[Takeaway 3]</li>
    </ul>
  </div>

  <!-- STATISTICS (if quantitative data exists) -->
  <div class="stats-grid">
    <div class="stat-card">
      <div class="stat-value">[Number]</div>
      <div class="stat-label">[Label]</div>
    </div>
    <!-- Repeat for key metrics -->
  </div>

  <!-- KEY FINDINGS -->
  <h2>Key Findings</h2>

  <div class="finding-card critical">
    <div class="finding-card-header">
      <h3 class="finding-title">[Finding Title]</h3>
      <span class="confidence-badge high">[Confidence]%</span>
    </div>
    <p>[Finding description and analysis]</p>
    <details>
      <summary>Supporting Sources ([count])</summary>
      <ul>
        <li><a href="[url]">[Source title]</a> - [contribution]</li>
      </ul>
