  <div class="timeline">
    <div class="timeline-item">
      <div class="timeline-date">Iteration 1 - [date]</div>
      <p>[Summary of iteration activities]</p>
      <p><small>Sources: [count] | Duration: [time]</small></p>
    </div>
    <!-- Repeat for iterations -->
  </div>

  <!-- LIMITATIONS -->
